        (CAST(9.5 AS DECIMAL(3,1)), ARRAY[8311781, 8687556, 9108483, 11600133, 13114176, 14910166, 15962164, 16015865, 16015877, 16098490, 16882696, 17498288, 18730597, 19231759, 19300649, 20525352, 20662702, 21148550, 21615012, 21686920, 22067434, 22336008, 23177748, 23473877, 24025917, 24518361, 24606072, 24686923, 25539649, 25747950, 25748242, 25795242, 26475278, 27103547, 27997406, 28047813, 28086640, 28111347, 28680882, 28681930, 28692711, 28761398, 28788289, 28788305, 29099959, 29181488, 29292935, 29390897, 29596800, 29609573, 29644174, 29644656, 30385031, 30385350, 31048980, 31379296, 31923755, 33219242, 33284867, 33363513, 33949869, 34020867, 34196593, 34335914, 34598226, 34722292, 34773466, 35351309, 35409631, 35409635, 35409706, 35409970, 35411748, 35415583, 36396570, 37202917, 37484433, 37777367, 38736703, 38740064, 38740073, 38759369, 39749439, 40031658, 40218552, 40229108, 40229125, 40604572, 42206925, 42535952, 42628196, 42852507, 42932236, 43388538, 43687164, 44271049, 44600151, 44600281, 45031637, 45662767, 45663127, 45761163, 45848907, 46094283, 46096005, 46193917, 46259386, 46326775, 46346599, 46346618, 46451176, 46670239, 46673951, 46776243, 46834017, 46894177, 47006571, 47076062, 47150709, 47166243, 47186501, 47287504, 47287884, 47324759, 47326586, 47451439, 47550387, 47561619, 47768805, 47846246, 47932887, 48077180, 48340103, 48363805, 48365630, 48371036, 48857906, 49037369, 49275503, 49331635, 49744408, 49746210, 49850114, 49935168, 50379693, 51135028, 51372746, 51790187, 51792369, 51794910, 51800759, 51804534, 51936941, 51938766]),
        (CAST(9.6 AS DECIMAL(3,1)), ARRAY[14909926, 16844391, 17088370, 17498300, 18519225, 23122440, 23452349, 25297716, 25785094, 28681040, 28716810, 29605484, 30561510, 31599600, 31669213, 32746603, 33535519, 34270364, 35149529, 35149530, 35408848, 35409121, 35423638, 35516425, 36628530, 37189011, 37189020, 37317463, 37584495, 37584559, 38740028, 38740034, 38740090, 40029195, 40165874, 40166321, 40774586, 41361941, 41672531, 41725558, 42603670, 43056766, 43272561, 43396882, 44020932, 44052577, 44219475, 44600279, 44731495, 44802997, 44803001, 45102696, 46203586, 46247072, 46352102, 46406526, 46845517, 46881237, 46978202, 47134915, 47166255, 47287476, 47287831, 47325356, 47557098, 47846308, 47855224, 48371035, 48628942, 48748548, 48850617, 49850282, 50016615, 50029030, 50361352, 51665451, 51793924, 51995298]),
        (CAST(9.7 AS DECIMAL(3,1)), ARRAY[10953180, 14900391, 16014163, 17719557, 21692591, 23740368, 24098969, 30693517, 38202022, 38758356, 40229119, 40774582, 41838623, 44127610, 44803000, 44905122, 46326777, 46513544, 46606601, 46671019, 46777115, 47006600, 47076119, 47287818, 48313101, 48443851, 48594147, 48594235, 50028765, 51793905]),
        (CAST(9.8 AS DECIMAL(3,1)), ARRAY[19582065, 19582075, 23491904, 25431730, 25586319, 29403016, 33474524, 34448671, 35410831, 38737050, 38767939, 41838716, 44766555, 46026222, 49850278, 49951268, 50119582]),
        (CAST(9.9 AS DECIMAL(3,1)), ARRAY[35529533, 37317474, 40296908, 45496892, 46606588]),
        (CAST(10.0 AS DECIMAL(3,1)), ARRAY[10923266, 18730595, 19984198, 28072939, 31258982, 35074208, 35529575, 40913352, 41361942, 43635996, 49293313, 49951287])
    ) AS t(comfort_score_band, route_ids)
),

route_scores AS (

    SELECT
        CAST(route_id AS BIGINT) AS route_id,
        comfort_score_band

    FROM route_score_band_chunks
    CROSS JOIN UNNEST(route_ids) AS u(route_id)
),

srp_base AS (

    SELECT
        a.mri_session_id,
        a.route_id,
        CAST(a.doj AS DATE) AS doj,

        CASE
            WHEN CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V0%')) > 0 THEN 'V0'
            WHEN CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V1%')) > 0 THEN 'V1'
            WHEN CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V2%')) > 0 THEN 'V2'
            ELSE NULL
        END AS variant,

        rs.comfort_score_band

    FROM user_interaction.search_route_details a

    INNER JOIN route_scores rs
        ON CAST(a.route_id AS BIGINT) = rs.route_id

    WHERE a.country = 'IND'
      AND a.os = 'Android'
      AND a.__time >= TIMESTAMP '2026-06-02 00:00:00'
      AND a.__time <  TIMESTAMP '2026-06-08 00:00:00'

      AND a.mri_session_id IS NOT NULL
      AND a.route_id IS NOT NULL
      AND a.doj IS NOT NULL
      AND a.src_id IS NOT NULL
      AND a.dest_id IS NOT NULL

      AND (
            CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V0%')) > 0
         OR CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V1%')) > 0
         OR CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V2%')) > 0
      )
),

seat_clicks AS (

    SELECT DISTINCT
        b.mri_session_id,
        b.route_id,
        CAST(b.doj AS DATE) AS doj

    FROM user_interaction.seat_layout_details b

    INNER JOIN route_scores rs
        ON CAST(b.route_id AS BIGINT) = rs.route_id

    WHERE b.country = 'IND'
      AND b.os = 'Android'
      AND b.__time >= TIMESTAMP '2026-06-02 00:00:00'
      AND b.__time <  TIMESTAMP '2026-06-08 00:00:00'

      AND b.mri_session_id IS NOT NULL
      AND b.route_id IS NOT NULL
      AND b.doj IS NOT NULL
      AND b.src_id IS NOT NULL
      AND b.dest_id IS NOT NULL
),

agg AS (

    SELECT
        a.variant,
        a.comfort_score_band,
        COUNT(*) AS srp_loads,
        COUNT(b.route_id) AS sl_loads,
        ROUND(
            100.0 * COUNT(b.route_id) / NULLIF(COUNT(*), 0),
            3
        ) AS ctr_pct

    FROM srp_base a

    LEFT JOIN seat_clicks b
        ON a.mri_session_id = b.mri_session_id
       AND a.route_id = b.route_id
       AND a.doj = b.doj

    WHERE a.variant IS NOT NULL

    GROUP BY
        1, 2
)

SELECT
    variant,
    comfort_score_band,
    srp_loads,
    sl_loads,
    ctr_pct

FROM agg

ORDER BY
    variant,
    comfort_score_band;
